function validate([grid, limits, k]) {
  const n = grid.length;
  if (n < 1 || n > 500) return 'grid needs 1 to 500 rows.';
  const m = grid[0].length;
  if (m < 1 || m > 500) return 'Each row of grid needs 1 to 500 values.';
  if (grid.some(row => row.length !== m)) return 'Every row of grid must have the same length.';
  if (grid.some(row => row.some(v => v < 0 || v > 100000))) return 'Each value in grid is between 0 and 10^5.';
  if (limits.length !== n) return 'limits needs exactly one entry per row of grid.';
  if (limits.some(limit => limit < 0 || limit > m)) return 'Each limit is between 0 and the row length.';
  const allowed = Math.min(n * m, limits.reduce((a, b) => a + b, 0));
  if (k < 0 || k > allowed) return 'k is between 0 and min(n * m, sum(limits)).';
  return null;
}

