function maxSum(grid, limits, k) {
  const candidates = [];
  for (let i = 0; i < grid.length; i++) {
    const row = [...grid[i]].sort((a, b) => b - a);
    for (let j = 0; j < limits[i]; j++) {
      candidates.push(row[j]);
    }
  }

  candidates.sort((a, b) => b - a);
  let total = 0;
  for (let j = 0; j < k; j++) {
    total += candidates[j];
  }
  return total;
}

