function maxSum(grid, limits, k) {
  // Try every subset of cells and keep the best one that respects k and every row's limit.
  const cells = [];
  grid.forEach((values, row) => values.forEach(value => cells.push([row, value])));
  let best = 0;
  for (let mask = 0; mask < (1 << cells.length); mask++) {
    const used = new Array(grid.length).fill(0);
    let count = 0, sum = 0, allowed = true;
    for (let c = 0; c < cells.length; c++) {
      if (((mask >> c) & 1) === 0) continue;
      const [row, value] = cells[c];
      count++;
      sum += value;
      used[row]++;
      if (used[row] > limits[row]) allowed = false;
    }
    if (allowed && count <= k && sum > best) best = sum;
  }
  return best;
}

