function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 3);
  const m = large ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 4);
  const top = large ? 100000 : [0, 3, 10, 100000][Math.floor(rand() * 4)];
  const grid = Array.from({ length: n }, () => Array.from({ length: m }, () => Math.floor(rand() * (top + 1))));
  // Limits range from 0 to the full row; k never exceeds what the limits and the grid allow.
  const limits = Array.from({ length: n }, () => Math.floor(rand() * (m + 1)));
  const cap = Math.min(n * m, limits.reduce((a, b) => a + b, 0));
  const roll = rand();
  const k = roll < 0.15 ? cap : roll < 0.25 ? 0 : Math.floor(rand() * (cap + 1));
  return [grid, limits, k];
}
